"use client";

import { api } from "@/lib/api";
import { useIdempotency } from "@/lib/idempotency";
import { useState } from "react";
import { useForm, FormProvider } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { toast } from "sonner";
import FormField from "@/components/form/formField";
import AuthGate from "@/components/auth-gate";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Spinner } from "@/components/ui/spinner";

const passwordSchema = z.object({
  currentPassword: z.string().min(1, "Current password is required"),
  newPassword: z.string().min(8, "Password must be at least 8 characters"),
});

type PasswordFormData = z.infer<typeof passwordSchema>;

const emailSchema = z.object({
  newEmail: z.string().email("Invalid email address"),
  emailPassword: z.string().min(1, "Password is required"),
});

type EmailFormData = z.infer<typeof emailSchema>;

/**
 * Split from the exported wrapper below so the gate sits above the component, not above its JSX:
 * mounted inside the gate, neither password nor email request is ever issued without a session.
 */
function SettingsPage() {
  const [changingPassword, setChangingPassword] = useState(false);
  const [changingEmail, setChangingEmail] = useState(false);
  // Two forms, two intents: a password change must not reuse the email change's key, or the
  // second submission is rejected as the same request as the first.
  const passwordIdem = useIdempotency();
  const emailIdem = useIdempotency();

  const passwordMethods = useForm<PasswordFormData>({
    resolver: zodResolver(passwordSchema),
    defaultValues: { currentPassword: "", newPassword: "" },
  });

  const emailMethods = useForm<EmailFormData>({
    resolver: zodResolver(emailSchema),
    defaultValues: { newEmail: "", emailPassword: "" },
  });

  async function onPasswordChange(data: PasswordFormData) {
    setChangingPassword(true);

    try {
      await passwordIdem.run((idempotencyKey) =>
        api("/profile/password", {
          method: "PUT",
          body: JSON.stringify(data),
          idempotencyKey,
        })
      );
      toast.success("Password updated successfully.");
      passwordMethods.reset();
    } catch (err: any) {
      toast.error(err.message || "Failed to update password");
    } finally {
      setChangingPassword(false);
    }
  }

  async function onEmailChange(data: EmailFormData) {
    setChangingEmail(true);

    try {
      await emailIdem.run((idempotencyKey) =>
        api("/profile/email", {
          method: "PUT",
          body: JSON.stringify({
            currentPassword: data.emailPassword,
            newEmail: data.newEmail,
          }),
          idempotencyKey,
        })
      );
      toast.success("Email updated successfully.");
      emailMethods.reset();
    } catch (err: any) {
      toast.error(err.message || "Failed to update email");
    } finally {
      setChangingEmail(false);
    }
  }

  return (
    <div className="mx-auto max-w-2xl p-6">
      <h1 className="mb-6 text-3xl font-bold">Settings</h1>

      {/* Change Password */}
      <Card className="mb-6">
        <CardHeader>
          <CardTitle>Change Password</CardTitle>
        </CardHeader>
        <CardContent>
          <FormProvider {...passwordMethods}>
            <form
              onSubmit={passwordMethods.handleSubmit(onPasswordChange)}
              className="flex flex-col gap-4"
            >
              <FormField
                name="currentPassword"
                label="Current Password"
                type="password"
                autoComplete="current-password"
              />

              <FormField
                name="newPassword"
                label="New Password"
                type="password"
                minLength={8}
                autoComplete="new-password"
              />

              <Button type="submit" className="self-start" disabled={changingPassword}>
                {changingPassword ? <Spinner /> : "Update Password"}
              </Button>
            </form>
          </FormProvider>
        </CardContent>
      </Card>

      {/* Change Email */}
      <Card>
        <CardHeader>
          <CardTitle>Change Email</CardTitle>
        </CardHeader>
        <CardContent>
          <FormProvider {...emailMethods}>
            <form
              onSubmit={emailMethods.handleSubmit(onEmailChange)}
              className="flex flex-col gap-4"
            >
              <FormField name="newEmail" label="New Email" type="email" placeholder="Email" />

              <FormField
                name="emailPassword"
                label="Current Password"
                type="password"
                autoComplete="current-password"
              />

              <Button type="submit" className="self-start" disabled={changingEmail}>
                {changingEmail ? <Spinner /> : "Update Email"}
              </Button>
            </form>
          </FormProvider>
        </CardContent>
      </Card>
    </div>
  );
}

export default function SettingsRoute() {
  return (
    <AuthGate>
      <SettingsPage />
    </AuthGate>
  );
}
